<?php

namespace App\Services;

use Illuminate\Support\Str;

/**
 * Random secrets generated by the server (never hardcoded, never returned by the API).
 */
class Codes
{
    /** No 0/O, 1/I/L: easy to read and type from an email. */
    private const ALPHABET = 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';

    public static function identificationCode(int $length): string
    {
        $max = strlen(self::ALPHABET) - 1;
        $code = '';
        for ($i = 0; $i < $length; $i++) {
            $code .= self::ALPHABET[random_int(0, $max)];
        }

        return $code;
    }

    public static function numeric(int $length): string
    {
        $code = '';
        for ($i = 0; $i < $length; $i++) {
            $code .= (string) random_int(0, 9);
        }

        return $code;
    }

    /** URL-safe token for one-time links (stored as sha256 only). */
    public static function linkToken(): string
    {
        return Str::random(64);
    }

    public static function lookupHash(string $token): string
    {
        return hash('sha256', 'link|'.$token);
    }
}
